CREATE DATABASE IF NOT EXISTS boutique_electronique CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE boutique_electronique;
CREATE TABLE IF NOT EXISTS admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(80) NOT NULL,description TEXT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,stock INT UNSIGNED NOT NULL DEFAULT 0,image VARCHAR(255) NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_products_active_category(is_active,category))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NULL,address VARCHAR(500) NOT NULL,notes TEXT NULL,total DECIMAL(12,2) NOT NULL,status ENUM('pending','confirmed','shipped','delivered','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,product_name VARCHAR(160) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INT UNSIGNED NOT NULL,CONSTRAINT fk_order_items_order FOREIGN KEY(order_id)REFERENCES orders(id)ON DELETE CASCADE,CONSTRAINT fk_order_items_product FOREIGN KEY(product_id)REFERENCES products(id)ON DELETE SET NULL)ENGINE=InnoDB;
